 "content": "from collections import Counter, deque


def _components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            pts = set()
            while q:
                x, y = q.popleft()
                pts.add((x, y))
                for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                    if (0 <= nx < h and 0 <= ny < w and (nx, ny) not in seen
                            and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            out.append((color, pts))
    return out


def _thin_l(pts):
    rows = {r for r, _ in pts}
    cols = {c for _, c in pts}
    if len(rows) < 2 or len(cols) < 2:
        return False
    # A one-cell-wide corner: the union of one complete row and one complete column.
    return any(pts == ({(r, c) for c in cols} | {(r0, c) for r0 in rows})
               for r, c in pts)


def _line(pts):
    return len({r for r, _ in pts}) == 1 or len({c for _, c in pts}) == 1


def _missing_corner_rectangle(pts):
    rs = [r for r, _ in pts]
    cs = [c for _, c in pts]
    h = max(rs) - min(rs) + 1
    w = max(cs) - min(cs) + 1
    if h < 2 or w < 2 or len(pts) != h * w - 1:
        return False
    return any((r, c) not in pts for r in (min(rs), max(rs))
               for c in (min(cs), max(cs)))


def transform(grid):
    g = [row[:] for row in grid]
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    comps = _components(g, bg)

    # The long right-angle stroke is the color key. Its color is applied to the
    # near-rectangular object with one missing corner.
    ls = [(color, pts) for color, pts in comps if _thin_l(pts)]
    if ls:
        key_color, _ = max(ls, key=lambda item: (len(item[1]),
                                                  max(r for r, _ in item[1]) - min(r for r, _ in item[1]) +
                                                  max(c for _, c in item[1]) - min(c for _, c in item[1])))
        targets = [(color, pts) for color, pts in comps
                   if color != key_color and _missing_corner_rectangle(pts)]
        if targets:
            # The matching compact corner object is the smallest such component.
            _, target = min(targets, key=lambda item: len(item[1]))
            for r, c in target:
                g[r][c] = key_color
            return g

    # Straight-line key: match another straight stroke of twice its length.
    lines = [(color, pts) for color, pts in comps if _line(pts) and len(pts) >= 2]
    if lines:
        key_color, key = min(lines, key=lambda item: (len(item[1]), item[0]))
        candidates = [(color, pts) for color, pts in lines
                      if color != key_color and len(pts) == 2 * len(key)]
        if candidates:
            _, target = min(candidates, key=lambda item: (len(item[1]), item[0]))
            for r, c in target:
                g[r][c] = key_color
    return g
