 "content": "from collections import Counter, deque


def _components(grid, bg):
    seen, out = set(), []
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color == bg or (r, c) in seen:
                continue
            pts, q = set(), deque([(r, c)])
            seen.add((r, c))
            while q:
                x, y = q.popleft()
                pts.add((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if (0 <= nx < len(grid) and 0 <= ny < len(grid[nx])
                            and (nx,ny) not in seen and grid[nx][ny] == color):
                        seen.add((nx,ny)); q.append((nx,ny))
            out.append((color, pts))
    return out


def _elbow(pts):
    r0=min(r for r,c in pts); r1=max(r for r,c in pts)
    c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    h,w=r1-r0+1,c1-c0+1
    if len(pts)!=h+w-1: return None
    for r in (r0,r1):
        for c in (c0,c1):
            if pts==({(r,y) for y in range(c0,c1+1)} | {(x,c) for x in range(r0,r1+1)}):
                # horizontal arm extends right/left from its elbow
                return r,c,(1 if c==c0 else -1)
    return None


def transform(grid):
    out=[row[:] for row in grid]
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps=_components(grid,bg)
    ls=[(color,pts,_elbow(pts)) for color,pts in comps]
    ls=[x for x in ls if x[2] is not None]
    if not ls: return out
    keycolor,key,(kr,kc,hdir)=max(ls,key=lambda x:len(x[1]))
    # Target the nearest separate component on the side opposite the horizontal arm.
    candidates=[]
    for color,pts in comps:
        if color==keycolor: continue
        if hdir>0 and max(c for r,c in pts)<kc or hdir<0 and min(c for r,c in pts)>kc:
            d=min(abs(r-x)+abs(c-y) for r,c in pts for x,y in key)
            candidates.append((d,-len(pts),color,pts))
    if candidates:
        _,_,_,target=min(candidates)
        for r,c in target: out[r][c]=keycolor
    return out
